// Windows coordinator: isolated 3017 only; every API request is intercepted.
import {chromium,expect} from '@playwright/test';
const origin=process.env.OTTLOG_PARITY_ORIGIN||'http://127.0.0.1:3017';
if(!/^http:\/\/(127\.0\.0\.1|localhost):3017$/.test(origin))throw Error('Use isolated 3017');
const browser=await chromium.launch();
try {for(const viewport of [{width:1440,height:900},{width:390,height:844},{width:375,height:667}]){
 const context=await browser.newContext({viewport}),page=await context.newPage(),writes=[];
 const states={reminders:{version:1,items:[{id:'a',title:'甲低',note:'',group:'工作',kind:'plant',minutes:0,enabled:true,priority:'low',timePeriod:'free',createdAt:1},{id:'b',title:'乙高',note:'',group:'生活',kind:'plant',minutes:0,enabled:true,priority:'high',timePeriod:'free',createdAt:2}],done:{}},domains:{version:1,domains:[],completedGoals:[]},memos:{version:1,notes:[{id:'m',title:'夹具便签',body:'原正文',color:'blue',tags:['工作'],pinned:false,createdAt:'2026-11-01T00:00:00Z',updatedAt:'2026-11-01T00:00:00Z'}]}};
 await page.addInitScript(()=>{const original=Storage.prototype.setItem;Storage.prototype.setItem=function(k,v){if(window.__sortFailLocal&&k.startsWith('ottlog-tool-v1:')&&k.endsWith(':reminders'))throw Error('isolated storage failure');return original.call(this,k,v);};});
 let fail=false;const failures=[],errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.route('**/api/**',route=>{const req=route.request(),path=new URL(req.url()).pathname,key=path.match(/^\/api\/personal-tools\/([^/]+)$/)?.[1];if(path.startsWith('/api/account/'))return route.fulfill({json:{authenticated:true,userName:'sort-fixture',csrfToken:'isolated'}});if(key){if(req.method()==='PUT'){writes.push({key,data:req.postDataJSON().data});if(fail&&key==='reminders'&&req.postDataJSON().data.sort?.field==='created'){failures.push(structuredClone(req.postDataJSON().data));return route.fulfill({status:500,json:{message:'fixture failure'}});}states[key]=req.postDataJSON().data;}return route.fulfill({json:{data:states[key]??null}});}return route.fulfill({json:{enabled:false,reminders:[],posts:[],items:[]}});});
 const button=name=>page.getByRole('button',{name,exact:true}),main=page.locator('.daily-habit-pages'),bar=page.locator('.applied-options');
 await page.goto(origin+'/daily');await expect(bar).toContainText('优先度');await expect(bar).toContainText('降序');
 const baseline=writes.length,count=await page.locator('.daily-reminder-count').textContent();
 await page.locator('.daily-core-filter').filter({hasText:/^全部$/}).click();await expect(page.locator('.daily-neglected')).toBeVisible();await expect(page.locator('.daily-reminder-count')).toHaveText(count);await expect(main.locator('.habit-sort-tile').first()).toHaveAttribute('id','habit-sort-b');expect(writes.length).toBe(baseline);
 await button('排序习惯').click();await button('创建日期').click();await expect.poll(()=>states.reminders.sort?.field).toBe('created');await button('升序').click();await expect.poll(()=>states.reminders.sort).toEqual({field:'created',direction:'asc'});await expect(main.locator('.habit-sort-tile').first()).toHaveAttribute('id','habit-sort-a');await expect(page.locator('.sort-panel-footer')).toHaveCount(0);await button('关闭习惯排序').click();await expect(page.getByRole('dialog',{name:'保存修改？',exact:true})).toHaveCount(0);
 await button('筛选习惯').click();await page.getByRole('textbox',{name:'搜索习惯',exact:true}).fill('不存在');await button('关闭习惯筛选').click();await expect(page.locator('.daily-reminder-count')).toHaveText(count);await expect(page.locator('.daily-neglected')).toBeVisible();await button('清除当前筛选和排序').click();await expect.poll(()=>states.reminders.sort).toEqual({field:'priority',direction:'desc'});await expect(page.locator('.daily-core-filter').filter({hasText:/^全部$/})).toHaveAttribute('aria-pressed','true');await expect(main.locator('.habit-sort-tile')).toHaveCount(2);
 // A cloud failure retains the queued local order and uses the existing sync retry.
 fail=true;await button('排序习惯').click();await button('创建日期').click();await expect.poll(()=>failures.length).toBeGreaterThan(0);await expect(button('重新同步')).toBeVisible();const failed=failures.at(-1);fail=false;await expect.poll(()=>states.reminders.sort?.field,{timeout:15000}).toBe('created');expect(writes.at(-1).data.sort).toEqual(failed.sort);
 // A genuine local persistence failure keeps the exact sort operation for retry.
 await page.evaluate(()=>window.__sortFailLocal=true);await button('优先度').click();await expect(page.locator('.daily-sort-error').first()).toBeVisible();await page.evaluate(()=>window.__sortFailLocal=false);await button('重试').click();await expect.poll(()=>states.reminders.sort).toEqual({field:'priority',direction:'desc'});await button('关闭习惯排序').click();
 await expect(page.locator('.daily-page-toolbar .toolbar-reset')).toHaveCount(0);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1)).toBe(true);
 const original=JSON.stringify(states.memos);await page.goto(origin+'/memos');await button('排序便签').click();await button('便签排序：标题顺序').click();await expect(page.locator('.sort-panel-footer')).toHaveCount(0);await expect(bar).toContainText('标题顺序');await button('关闭便签排序').click();await bar.getByRole('button',{name:'清除当前筛选和排序'}).click();await expect(bar).toHaveCount(0);await expect(page.getByRole('dialog',{name:'排序便签',exact:true})).toHaveCount(0);expect(JSON.stringify(states.memos)).toBe(original);
 expect(errors).toEqual([]);await context.close();
}}finally{await browser.close();}
console.log('PASS isolated immediate sorting, reset retains view, independent reminders, memo clear without data writes');
